// preprocess.h - same preprocessing as in the notebook, done on the ESP32.
// raw feature vector (numeric + integer-coded categoricals)
//   -> log1p on heavy-tailed columns -> standardisation (z-score)
#pragma once
#include <math.h>
#include "preprocess_data.h"   // generated by the notebook

static inline void preprocess(const float *raw, float *out) {
    for (int i = 0; i < N_FEATURES; i++) {
        float v = raw[i];
        if (FEATURE_LOG1P[i]) v = log1pf(v > 0.0f ? v : 0.0f);
        out[i] = (v - FEATURE_MEAN[i]) * FEATURE_INV_STD[i];
    }
}
